#!/usr/bin/env python3
"""Refresh the small, ROM-free browser demo module from portable C."""
import base64
from pathlib import Path
import shutil
import sys
ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from port.build import build_ppu


def main():
    module = build_ppu()
    target = ROOT / 'port/demo'
    shutil.copyfile(module, target / 'ppu.wasm')
    encoded = base64.b64encode(module.read_bytes()).decode('ascii')
    (target / 'ppu-module.js').write_text(
        '// Generated by port/demo/build.py from port/ppu/ppu.c; no ROM data.\n'
        '// Embedded so index.html also works from file:// without a server.\n'
        f'globalThis.PPU_WASM_BASE64 = "{encoded}";\n')
    print('Browser demo module refreshed (portable C only).')


if __name__ == '__main__':
    main()
